00051 // --------------------------------------------------------------------------------------------------------------------
00052 // SAD
00053 // --------------------------------------------------------------------------------------------------------------------
00058 Distortion RdCostWeightPrediction::xGetSADw( const DistParam &rcDtParam )
00059 {
00060   const Pel            *piOrg      = rcDtParam.org.buf;
00061   const Pel            *piCur      = rcDtParam.cur.buf;
00062   const int             iCols      = rcDtParam.org.width;
00063   const int             iStrideCur = rcDtParam.cur.stride;
00064   const int             iStrideOrg = rcDtParam.org.stride;
00065   const ComponentID     compID     = rcDtParam.compID;
00066 
00067   CHECK( compID >= MAX_NUM_COMPONENT, "Invalid component" );
00068 
00069   const WPScalingParam &wpCur      = rcDtParam.wpCur[compID];
00070 
00071   const int             w0         = wpCur.w;
00072   const int             offset     = wpCur.offset;
00073   const int             shift      = wpCur.shift;
00074   const int             round      = wpCur.round;
00075   const int distortionShift = DISTORTION_PRECISION_ADJUSTMENT(rcDtParam.bitDepth);
00076 
00077   Distortion uiSum = 0;
00078 
00079 #if !U0040_MODIFIED_WEIGHTEDPREDICTION_WITH_BIPRED_AND_CLIPPING
00080   for(int iRows = rcDtParam.org.height; iRows != 0; iRows-- )
00081   {
00082     for (int n = 0; n < iCols; n++ )
00083     {
00084       const Pel pred = ( (w0*piCur[n] + round) >> shift ) + offset ;
00085 
00086       uiSum += abs( piOrg[n] - pred );
00087     }
00088     if (rcDtParam.maximumDistortionForEarlyExit <  ( uiSum >> distortionShift))
00089     {
00090       return uiSum >> distortionShift;
00091     }
00092     piOrg += iStrideOrg;
00093     piCur += iStrideCur;
00094   }
00095 
00096   //rcDtParam.compID = MAX_NUM_COMPONENT;  // reset for DEBUG (assert test)
00097 #else
00098   ClpRng clpRng; // this just affects the cost
00099   clpRng.min = 0;
00100   clpRng.max = (1 << rcDtParam.bitDepth) - 1;
00101 
00102   // Default weight
00103   if (w0 == 1 << shift)
00104   {
00105     // no offset
00106     if (offset == 0)
00107     {
00108       for(int iRows = rcDtParam.org.height; iRows != 0; iRows-- )
00109       {
00110         for (int n = 0; n < iCols; n++ )
00111         {
00112           uiSum += abs( piOrg[n] - piCur[n] );
00113         }
00114         if (rcDtParam.maximumDistortionForEarlyExit <  ( uiSum >> distortionShift))
00115         {
00116           return uiSum >> distortionShift;
00117         }
00118         piOrg += iStrideOrg;
00119         piCur += iStrideCur;
00120       }
00121     }
00122     else
00123     {
00124       // Lets not clip for the bipredictive case since clipping should be done after
00125       // combining both elements. Unfortunately the code uses the suboptimal "subtraction"
00126       // method, which is faster but introduces the clipping issue (therefore Bipred is suboptimal).
00127       if (rcDtParam.isBiPred)
00128       {
00129         for(int iRows = rcDtParam.org.height; iRows != 0; iRows-- )
00130         {
00131           for (int n = 0; n < iCols; n++ )
00132           {
00133             uiSum += abs( piOrg[n] - (piCur[n] + offset) );
00134           }
00135           if (rcDtParam.maximumDistortionForEarlyExit <  ( uiSum >> distortionShift))
00136           {
00137             return uiSum >> distortionShift;
00138           }
00139 
00140           piOrg += iStrideOrg;
00141           piCur += iStrideCur;
00142         }
00143       }
00144       else
00145       {
00146         for(int iRows = rcDtParam.org.height; iRows != 0; iRows-- )
00147         {
00148           for (int n = 0; n < iCols; n++ )
00149           {
00150             const Pel pred = ClipPel( piCur[n] + offset, clpRng);
00151 
00152             uiSum += abs( piOrg[n] - pred );
00153           }
00154           if (rcDtParam.maximumDistortionForEarlyExit <  ( uiSum >> distortionShift))
00155           {
00156             return uiSum >> distortionShift;
00157           }
00158           piOrg += iStrideOrg;
00159           piCur += iStrideCur;
00160         }
00161       }
00162     }
00163   }
00164   else
00165   {
00166     // Lets not clip for the bipredictive case since clipping should be done after
00167     // combining both elements. Unfortunately the code uses the suboptimal "subtraction"
00168     // method, which is faster but introduces the clipping issue (therefore Bipred is suboptimal).
00169     if (rcDtParam.isBiPred)
00170     {
00171       for(int iRows = rcDtParam.org.height; iRows != 0; iRows-- )
00172       {
00173         for (int n = 0; n < iCols; n++ )
00174         {
00175           const Pel pred = ( (w0*piCur[n] + round) >> shift ) + offset ;
00176           uiSum += abs( piOrg[n] - pred );
00177         }
00178         if (rcDtParam.maximumDistortionForEarlyExit <  ( uiSum >> distortionShift))
00179         {
00180           return uiSum >> distortionShift;
00181         }
00182 
00183         piOrg += iStrideOrg;
00184         piCur += iStrideCur;
00185       }
00186     }
00187     else
00188     {
00189       if (offset == 0)
00190       {
00191         for(int iRows = rcDtParam.org.height; iRows != 0; iRows-- )
00192         {
00193           for (int n = 0; n < iCols; n++ )
00194           {
00195             const Pel pred = ClipPel( (w0*piCur[n] + round) >> shift, clpRng);
00196 
00197             uiSum += abs( piOrg[n] - pred );
00198           }
00199           if (rcDtParam.maximumDistortionForEarlyExit <  ( uiSum >> distortionShift))
00200           {
00201             return uiSum >> distortionShift;
00202           }
00203           piOrg += iStrideOrg;
00204           piCur += iStrideCur;
00205         }
00206       }
00207       else
00208       {
00209         for(int iRows = rcDtParam.org.height; iRows != 0; iRows-- )
00210         {
00211           for (int n = 0; n < iCols; n++ )
00212           {
00213             const Pel pred = ClipPel(((w0*piCur[n] + round) >> shift ) + offset,  clpRng) ;
00214 
00215             uiSum += abs( piOrg[n] - pred );
00216           }
00217           if (rcDtParam.maximumDistortionForEarlyExit <  ( uiSum >> distortionShift))
00218           {
00219             return uiSum >> distortionShift;
00220           }
00221           piOrg += iStrideOrg;
00222           piCur += iStrideCur;
00223         }
00224       }
00225     }
00226   }
00227   //rcDtParam.compIdx = MAX_NUM_COMPONENT;  // reset for DEBUG (assert test)
00228 #endif
00229 
00230   return uiSum >> distortionShift;
00231 }
00232 
