00234 // --------------------------------------------------------------------------------------------------------------------
00235 // SSE
00236 // --------------------------------------------------------------------------------------------------------------------
00241 Distortion RdCostWeightPrediction::xGetSSEw( const DistParam &rcDtParam )
00242 {
00243   const Pel            *piOrg      = rcDtParam.org.buf;
00244   const Pel            *piCur      = rcDtParam.cur.buf;
00245   const int             iCols      = rcDtParam.org.width;
00246   const int             iStrideCur = rcDtParam.cur.stride;
00247   const int             iStrideOrg = rcDtParam.org.stride;
00248   const ComponentID     compID     = rcDtParam.compID;
00249 
00250   CHECK( rcDtParam.subShift != 0, "Subshift not supported" ); // NOTE: what is this protecting?
00251   CHECK( compID >= MAX_NUM_COMPONENT, "Invalid channel" );
00252 
00253   const WPScalingParam &wpCur           = rcDtParam.wpCur[compID];
00254   const int             w0              = wpCur.w;
00255   const int             offset          = wpCur.offset;
00256   const int             shift           = wpCur.shift;
00257   const int             round           = wpCur.round;
00258   const uint32_t distortionShift = DISTORTION_PRECISION_ADJUSTMENT(rcDtParam.bitDepth) << 1;
00259 
00260   Distortion sum = 0;
00261 
00262 #if !U0040_MODIFIED_WEIGHTEDPREDICTION_WITH_BIPRED_AND_CLIPPING
00263   for(int iRows = rcDtParam.org.height ; iRows != 0; iRows-- )
00264   {
00265     for (int n = 0; n < iCols; n++ )
00266     {
00267       const Pel pred     = ( (w0*piCur[n] + round) >> shift ) + offset ;
00268       const Pel residual = piOrg[n] - pred;
00269       sum += ( Distortion(residual) * Distortion(residual) ) >> distortionShift;
00270     }
00271     piOrg += iStrideOrg;
00272     piCur += iStrideCur;
00273   }
00274 
00275   //rcDtParam.compIdx = MAX_NUM_COMPONENT; // reset for DEBUG (assert test)
00276 #else
00277   if (rcDtParam.isBiPred)
00278   {
00279     for(int iRows = rcDtParam.org.height ; iRows != 0; iRows-- )
00280     {
00281       for (int n = 0; n < iCols; n++ )
00282       {
00283         const Pel pred     = ( (w0*piCur[n] + round) >> shift ) + offset ;
00284         const Pel residual = piOrg[n] - pred;
00285         sum += ( Distortion(residual) * Distortion(residual) ) >> distortionShift;
00286       }
00287       piOrg += iStrideOrg;
00288       piCur += iStrideCur;
00289     }
00290   }
00291   else
00292   {
00293     ClpRng clpRng;  // this just affects the cost - fix this later
00294     clpRng.min = 0;
00295     clpRng.max = (1 << rcDtParam.bitDepth) - 1;
00296 
00297     for(int iRows = rcDtParam.org.height; iRows != 0; iRows-- )
00298     {
00299       for (int n = 0; n < iCols; n++ )
00300       {
00301         const Pel pred     = ClipPel(( (w0*piCur[n] + round) >> shift ) + offset, clpRng) ;
00302         const Pel residual = piOrg[n] - pred;
00303         sum += ( Distortion(residual) * Distortion(residual) ) >> distortionShift;
00304       }
00305       piOrg += iStrideOrg;
00306       piCur += iStrideCur;
00307     }
00308   }
00309 
00310   //rcDtParam.compIdx = MAX_NUM_COMPONENT; // reset for DEBUG (assert test)
00311 #endif
00312 
00313   return sum;
00314 }
00315 
