00317 // --------------------------------------------------------------------------------------------------------------------
00318 // HADAMARD with step (used in fractional search)
00319 // --------------------------------------------------------------------------------------------------------------------
00321 Distortion xCalcHADs2x2w( const WPScalingParam &wpCur, const Pel *piOrg, const Pel *piCur, int iStrideOrg, int iStrideCur, int iStep )
00322 {
00323   const int round  = wpCur.round;
00324   const int shift  = wpCur.shift;
00325   const int offset = wpCur.offset;
00326   const int w0     = wpCur.w;
00327 
00328   Distortion satd  = 0;
00329   TCoeff     diff[4];
00330   TCoeff     m[4];
00331 
00332   Pel   pred;
00333 
00334   pred    = ( (w0*piCur[0*iStep             ] + round) >> shift ) + offset ;
00335   diff[0] = piOrg[0             ] - pred;
00336   pred    = ( (w0*piCur[1*iStep             ] + round) >> shift ) + offset ;
00337   diff[1] = piOrg[1             ] - pred;
00338   pred    = ( (w0*piCur[0*iStep + iStrideCur] + round) >> shift ) + offset ;
00339   diff[2] = piOrg[iStrideOrg    ] - pred;
00340   pred    = ( (w0*piCur[1*iStep + iStrideCur] + round) >> shift ) + offset ;
00341   diff[3] = piOrg[iStrideOrg + 1] - pred;
00342 
00343   m[0] = diff[0] + diff[2];
00344   m[1] = diff[1] + diff[3];
00345   m[2] = diff[0] - diff[2];
00346   m[3] = diff[1] - diff[3];
00347 
00348   satd += abs(m[0] + m[1]);
00349   satd += abs(m[0] - m[1]);
00350   satd += abs(m[2] + m[3]);
00351   satd += abs(m[2] - m[3]);
00352 
00353   return satd;
00354 }
00355 
00356 
00358 Distortion xCalcHADs4x4w( const WPScalingParam &wpCur, const Pel *piOrg, const Pel *piCur, int iStrideOrg, int iStrideCur, int iStep )
00359 {
00360   const int round  = wpCur.round;
00361   const int shift  = wpCur.shift;
00362   const int offset = wpCur.offset;
00363   const int w0     = wpCur.w;
00364 
00365   Distortion satd = 0;
00366   TCoeff     diff[16];
00367   TCoeff     m[16];
00368   TCoeff     d[16];
00369 
00370 
00371   for(int k = 0; k < 16; k+=4 )
00372   {
00373     Pel pred;
00374     pred      = ( (w0*piCur[0*iStep] + round) >> shift ) + offset ;
00375     diff[k+0] = piOrg[0] - pred;
00376     pred      = ( (w0*piCur[1*iStep] + round) >> shift ) + offset ;
00377     diff[k+1] = piOrg[1] - pred;
00378     pred      = ( (w0*piCur[2*iStep] + round) >> shift ) + offset ;
00379     diff[k+2] = piOrg[2] - pred;
00380     pred      = ( (w0*piCur[3*iStep] + round) >> shift ) + offset ;
00381     diff[k+3] = piOrg[3] - pred;
00382 
00383     piCur += iStrideCur;
00384     piOrg += iStrideOrg;
00385   }
00386 
00387   /*===== hadamard transform =====*/
00388   m[ 0] = diff[ 0] + diff[12];
00389   m[ 1] = diff[ 1] + diff[13];
00390   m[ 2] = diff[ 2] + diff[14];
00391   m[ 3] = diff[ 3] + diff[15];
00392   m[ 4] = diff[ 4] + diff[ 8];
00393   m[ 5] = diff[ 5] + diff[ 9];
00394   m[ 6] = diff[ 6] + diff[10];
00395   m[ 7] = diff[ 7] + diff[11];
00396   m[ 8] = diff[ 4] - diff[ 8];
00397   m[ 9] = diff[ 5] - diff[ 9];
00398   m[10] = diff[ 6] - diff[10];
00399   m[11] = diff[ 7] - diff[11];
00400   m[12] = diff[ 0] - diff[12];
00401   m[13] = diff[ 1] - diff[13];
00402   m[14] = diff[ 2] - diff[14];
00403   m[15] = diff[ 3] - diff[15];
00404 
00405   d[ 0] = m[ 0] + m[ 4];
00406   d[ 1] = m[ 1] + m[ 5];
00407   d[ 2] = m[ 2] + m[ 6];
00408   d[ 3] = m[ 3] + m[ 7];
00409   d[ 4] = m[ 8] + m[12];
00410   d[ 5] = m[ 9] + m[13];
00411   d[ 6] = m[10] + m[14];
00412   d[ 7] = m[11] + m[15];
00413   d[ 8] = m[ 0] - m[ 4];
00414   d[ 9] = m[ 1] - m[ 5];
00415   d[10] = m[ 2] - m[ 6];
00416   d[11] = m[ 3] - m[ 7];
00417   d[12] = m[12] - m[ 8];
00418   d[13] = m[13] - m[ 9];
00419   d[14] = m[14] - m[10];
00420   d[15] = m[15] - m[11];
00421 
00422   m[ 0] = d[ 0] + d[ 3];
00423   m[ 1] = d[ 1] + d[ 2];
00424   m[ 2] = d[ 1] - d[ 2];
00425   m[ 3] = d[ 0] - d[ 3];
00426   m[ 4] = d[ 4] + d[ 7];
00427   m[ 5] = d[ 5] + d[ 6];
00428   m[ 6] = d[ 5] - d[ 6];
00429   m[ 7] = d[ 4] - d[ 7];
00430   m[ 8] = d[ 8] + d[11];
00431   m[ 9] = d[ 9] + d[10];
00432   m[10] = d[ 9] - d[10];
00433   m[11] = d[ 8] - d[11];
00434   m[12] = d[12] + d[15];
00435   m[13] = d[13] + d[14];
00436   m[14] = d[13] - d[14];
00437   m[15] = d[12] - d[15];
00438 
00439   d[ 0] = m[ 0] + m[ 1];
00440   d[ 1] = m[ 0] - m[ 1];
00441   d[ 2] = m[ 2] + m[ 3];
00442   d[ 3] = m[ 3] - m[ 2];
00443   d[ 4] = m[ 4] + m[ 5];
00444   d[ 5] = m[ 4] - m[ 5];
00445   d[ 6] = m[ 6] + m[ 7];
00446   d[ 7] = m[ 7] - m[ 6];
00447   d[ 8] = m[ 8] + m[ 9];
00448   d[ 9] = m[ 8] - m[ 9];
00449   d[10] = m[10] + m[11];
00450   d[11] = m[11] - m[10];
00451   d[12] = m[12] + m[13];
00452   d[13] = m[12] - m[13];
00453   d[14] = m[14] + m[15];
00454   d[15] = m[15] - m[14];
00455 
00456   for (int k=0; k<16; ++k)
00457   {
00458     satd += abs(d[k]);
00459   }
00460   satd = ((satd+1)>>1);
00461 
00462   return satd;
00463 }
00464 
00465 
00467 Distortion xCalcHADs8x8w( const WPScalingParam &wpCur, const Pel *piOrg, const Pel *piCur, int iStrideOrg, int iStrideCur, int iStep )
00468 {
00469   Distortion sad=0;
00470   TCoeff diff[64], m1[8][8], m2[8][8], m3[8][8];
00471   int iStep2 = iStep<<1;
00472   int iStep3 = iStep2 + iStep;
00473   int iStep4 = iStep3 + iStep;
00474   int iStep5 = iStep4 + iStep;
00475   int iStep6 = iStep5 + iStep;
00476   int iStep7 = iStep6 + iStep;
00477   const int round  = wpCur.round;
00478   const int shift  = wpCur.shift;
00479   const int offset = wpCur.offset;
00480   const int w0     = wpCur.w;
00481 
00482   Pel   pred;
00483 
00484   for(int k = 0; k < 64; k+=8 )
00485   {
00486     pred      = ( (w0*piCur[     0] + round) >> shift ) + offset ;
00487     diff[k+0] = piOrg[0] - pred;
00488     pred      = ( (w0*piCur[iStep ] + round) >> shift ) + offset ;
00489     diff[k+1] = piOrg[1] - pred;
00490     pred      = ( (w0*piCur[iStep2] + round) >> shift ) + offset ;
00491     diff[k+2] = piOrg[2] - pred;
00492     pred      = ( (w0*piCur[iStep3] + round) >> shift ) + offset ;
00493     diff[k+3] = piOrg[3] - pred;
00494     pred      = ( (w0*piCur[iStep4] + round) >> shift ) + offset ;
00495     diff[k+4] = piOrg[4] - pred;
00496     pred      = ( (w0*piCur[iStep5] + round) >> shift ) + offset ;
00497     diff[k+5] = piOrg[5] - pred;
00498     pred      = ( (w0*piCur[iStep6] + round) >> shift ) + offset ;
00499     diff[k+6] = piOrg[6] - pred;
00500     pred      = ( (w0*piCur[iStep7] + round) >> shift ) + offset ;
00501     diff[k+7] = piOrg[7] - pred;
00502 
00503     piCur += iStrideCur;
00504     piOrg += iStrideOrg;
00505   }
00506 
00507   //horizontal
00508   for (int j=0; j < 8; j++)
00509   {
00510     const int jj = j << 3;
00511     m2[j][0] = diff[jj  ] + diff[jj+4];
00512     m2[j][1] = diff[jj+1] + diff[jj+5];
00513     m2[j][2] = diff[jj+2] + diff[jj+6];
00514     m2[j][3] = diff[jj+3] + diff[jj+7];
00515     m2[j][4] = diff[jj  ] - diff[jj+4];
00516     m2[j][5] = diff[jj+1] - diff[jj+5];
00517     m2[j][6] = diff[jj+2] - diff[jj+6];
00518     m2[j][7] = diff[jj+3] - diff[jj+7];
00519 
00520     m1[j][0] = m2[j][0] + m2[j][2];
00521     m1[j][1] = m2[j][1] + m2[j][3];
00522     m1[j][2] = m2[j][0] - m2[j][2];
00523     m1[j][3] = m2[j][1] - m2[j][3];
00524     m1[j][4] = m2[j][4] + m2[j][6];
00525     m1[j][5] = m2[j][5] + m2[j][7];
00526     m1[j][6] = m2[j][4] - m2[j][6];
00527     m1[j][7] = m2[j][5] - m2[j][7];
00528 
00529     m2[j][0] = m1[j][0] + m1[j][1];
00530     m2[j][1] = m1[j][0] - m1[j][1];
00531     m2[j][2] = m1[j][2] + m1[j][3];
00532     m2[j][3] = m1[j][2] - m1[j][3];
00533     m2[j][4] = m1[j][4] + m1[j][5];
00534     m2[j][5] = m1[j][4] - m1[j][5];
00535     m2[j][6] = m1[j][6] + m1[j][7];
00536     m2[j][7] = m1[j][6] - m1[j][7];
00537   }
00538 
00539   //vertical
00540   for (int i=0; i < 8; i++)
00541   {
00542     m3[0][i] = m2[0][i] + m2[4][i];
00543     m3[1][i] = m2[1][i] + m2[5][i];
00544     m3[2][i] = m2[2][i] + m2[6][i];
00545     m3[3][i] = m2[3][i] + m2[7][i];
00546     m3[4][i] = m2[0][i] - m2[4][i];
00547     m3[5][i] = m2[1][i] - m2[5][i];
00548     m3[6][i] = m2[2][i] - m2[6][i];
00549     m3[7][i] = m2[3][i] - m2[7][i];
00550 
00551     m1[0][i] = m3[0][i] + m3[2][i];
00552     m1[1][i] = m3[1][i] + m3[3][i];
00553     m1[2][i] = m3[0][i] - m3[2][i];
00554     m1[3][i] = m3[1][i] - m3[3][i];
00555     m1[4][i] = m3[4][i] + m3[6][i];
00556     m1[5][i] = m3[5][i] + m3[7][i];
00557     m1[6][i] = m3[4][i] - m3[6][i];
00558     m1[7][i] = m3[5][i] - m3[7][i];
00559 
00560     m2[0][i] = m1[0][i] + m1[1][i];
00561     m2[1][i] = m1[0][i] - m1[1][i];
00562     m2[2][i] = m1[2][i] + m1[3][i];
00563     m2[3][i] = m1[2][i] - m1[3][i];
00564     m2[4][i] = m1[4][i] + m1[5][i];
00565     m2[5][i] = m1[4][i] - m1[5][i];
00566     m2[6][i] = m1[6][i] + m1[7][i];
00567     m2[7][i] = m1[6][i] - m1[7][i];
00568   }
00569 
00570   for (int j=0; j < 8; j++)
00571   {
00572     for (int i=0; i < 8; i++)
00573     {
00574       sad += (abs(m2[j][i]));
00575     }
00576   }
00577 
00578   sad=((sad+2)>>2);
00579 
00580   return sad;
00581 }
00582 
00583 
00585 Distortion RdCostWeightPrediction::xGetHADsw( const DistParam &rcDtParam )
00586 {
00587   const Pel        *piOrg      = rcDtParam.org.buf;
00588   const Pel        *piCur      = rcDtParam.cur.buf;
00589   const int         iRows      = rcDtParam.org.height;
00590   const int         iCols      = rcDtParam.org.width;
00591   const int         iStrideCur = rcDtParam.cur.stride;
00592   const int         iStrideOrg = rcDtParam.org.stride;
00593   const int         iStep      = rcDtParam.step;
00594   const ComponentID compIdx    = rcDtParam.compID;
00595   CHECK(compIdx>=MAX_NUM_COMPONENT, "Invalid component");
00596   const WPScalingParam &wpCur  = rcDtParam.wpCur[compIdx];
00597 
00598   Distortion uiSum = 0;
00599 
00600 
00601   if( ( iRows % 8 == 0) && (iCols % 8 == 0) )
00602   {
00603     const int iOffsetOrg = iStrideOrg<<3;
00604     const int iOffsetCur = iStrideCur<<3;
00605     for (int y=0; y<iRows; y+= 8 )
00606     {
00607       for (int x=0; x<iCols; x+= 8 )
00608       {
00609         uiSum += xCalcHADs8x8w( wpCur, &piOrg[x], &piCur[x*iStep], iStrideOrg, iStrideCur, iStep );
00610       }
00611       piOrg += iOffsetOrg;
00612       piCur += iOffsetCur;
00613     }
00614   }
00615   else if( ( iRows % 4 == 0) && (iCols % 4 == 0) )
00616   {
00617     const int iOffsetOrg = iStrideOrg<<2;
00618     const int iOffsetCur = iStrideCur<<2;
00619 
00620     for (int y=0; y<iRows; y+= 4 )
00621     {
00622       for (int x=0; x<iCols; x+= 4 )
00623       {
00624         uiSum += xCalcHADs4x4w( wpCur, &piOrg[x], &piCur[x*iStep], iStrideOrg, iStrideCur, iStep );
00625       }
00626       piOrg += iOffsetOrg;
00627       piCur += iOffsetCur;
00628     }
00629   }
00630   else
00631   {
00632     for (int y=0; y<iRows; y+=2 )
00633     {
00634       for (int x=0; x<iCols; x+=2 )
00635       {
00636         uiSum += xCalcHADs2x2w( wpCur, &piOrg[x], &piCur[x*iStep], iStrideOrg, iStrideCur, iStep );
00637       }
00638       piOrg += iStrideOrg;
00639       piCur += iStrideCur;
00640     }
00641   }
00642 
00643   return uiSum >> DISTORTION_PRECISION_ADJUSTMENT(rcDtParam.bitDepth);
00644 }
